def create_post(creds, location_id, tip): """Create a local post on GBP.""" headers = {'Authorization': f'Bearer {creds.token}', 'Content-Type': 'application/json'} url = f'https://mybusinessbusinessinformation.googleapis.com/v1/accounts/{ACCOUNT_ID}/locations/{location_id}/localPosts' payload = { "languageCode": "it", "summary": f"{tip['title']}

{tip['body']}

{tip['cta']}", "topicType": "STANDARD", "callToAction": { "actionType": "LEARN_MORE", "url": "https://decastropt.com" } } resp = requests.post(url, headers=headers, json=payload) return resp.status_code, resp.json()
